case Json.Num num -> {
    var v = num.value();
    // plain-form length without building the string: digits + sign + padding zeros / decimal point
    long digits = v.precision();
    long scale = v.scale();
    long len = digits + (v.signum() < 0 ? 1 : 0);
    if (scale < 0) {
        len += -scale;
    } else if (scale >= digits) {
        len += scale - digits + 2; // "0." + leading zeros
    } else if (scale > 0) {
        len += 1; // decimal point
    }
    yield len;
}

